1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	// Service 在 Store 之上实现班次交接的全部业务规则。
11	type Service struct {
12		store *Store
13		now   func() time.Time
14	}
15	
16	// NewService 创建业务服务。
17	func NewService(store *Store) *Service {
18		return &Service{store: store, now: time.Now}
19	}
20	
21	// nowAt 供测试固定处理时间。
22	func (svc *Service) nowAt(fn func() time.Time) { svc.now = fn }
23	
24	func clean(s string) string { return strings.TrimSpace(s) }
25	
26	func requireNonEmpty(field, v string) error {
27		if clean(v) == "" {
28			return fmt.Errorf("%w：%s不能为空", ErrInvalidInput, field)
29		}
30		return nil
31	}
32	
33	func intervalsOverlap(s1, e1, s2, e2 time.Time) bool {
34		// 前班结束恰好等于后班开始（端点相等）不算重叠。
35		return s1.Before(e2) && s2.Before(e1)
36	}
37	
38	// notePair 返回无序班次编号对，作为重叠说明的稳定键。
39	func notePair(a, b string) (string, string) {
40		if a <= b {
41			return a, b
42		}
43		return b, a
44	}
45	
46	func findShift(d *Data, id string) (*Shift, int) {
47		for i := range d.Shifts {
48			if d.Shifts[i].ID == id {
49				return &d.Shifts[i], i
50			}
51		}
52		return nil, -1
53	}
54	
55	func findItem(d *Data, id string) (*Item, int) {
56		for i := range d.Items {
57			if d.Items[i].ID == id {
58				return &d.Items[i], i
59			}
60		}
61		return nil, -1
62	}
63	
64	func findHandover(d *Data, id string) (*Handover, int) {
65		for i := range d.Handovers {
66			if d.Handovers[i].ID == id {
67				return &d.Handovers[i], i
68			}
69		}
70		return nil, -1
71	}
72	
73	func findEntry(h *Handover, itemID string) (*HandoverEntry, int) {
74		for i := range h.Entries {
75			if h.Entries[i].ItemID == itemID {
76				return &h.Entries[i], i
77			}
78		}
79		return nil, -1
80	}
81	
82	func findNote(d *Data, a, b string) *OverlapNote {
83		x, y := notePair(a, b)
84		for i := range d.Notes {
85			if d.Notes[i].ShiftA == x && d.Notes[i].ShiftB == y {
86				return &d.Notes[i]
87			}
88		}
89		return nil
90	}
91	
92	func hasNote(d *Data, a, b string) bool { return findNote(d, a, b) != nil }
93	
94	// CreateShift 建立班次。岗位、负责人必填，结束时间必须晚于开始时间。
95	// 同一岗位按实际时刻比较区间：前班结束恰好等于后班开始不算重叠；
96	// 与同岗位已存班次存在重叠时 overlapNote 必须非空，说明会一并保存。
97	// 不同岗位互不影响。
98	func (svc *Service) CreateShift(position, owner string, start, end time.Time, overlapNote string) (Shift, error) {
99		position = clean(position)
100		owner = clean(owner)
101		overlapNote = clean(overlapNote)
102		if err := requireNonEmpty("岗位", position); err != nil {
103			return Shift{}, err
104		}
105		if err := requireNonEmpty("负责人", owner); err != nil {
106			return Shift{}, err
107		}
108		if !end.After(start) {
109			return Shift{}, fmt.Errorf("%w：结束时间必须晚于开始时间（开始 %s，结束 %s）",
110				ErrInvalidInput, start.Format(time.RFC3339), end.Format(time.RFC3339))
111		}
112	
113		var created Shift
114		err := svc.store.mutate(func(d *Data) error {
115			var overlapping []Shift
116			for _, sh := range d.Shifts {
117				if sh.Position == position && intervalsOverlap(start, end, sh.Start, sh.End) {
118					overlapping = append(overlapping, sh)
119				}
120			}
121			if len(overlapping) > 0 && overlapNote == "" {
122				ids := make([]string, len(overlapping))
123				for i, sh := range overlapping {
124					ids[i] = fmt.Sprintf("%s（%s ~ %s）", sh.ID, sh.Start.Format(time.RFC3339), sh.End.Format(time.RFC3339))
125				}
126				return fmt.Errorf("%w：与同岗位班次 %s 区间重叠，必须填写重叠说明",
127					ErrOverlap, strings.Join(ids, "、"))
128			}
129	
130			d.ShiftSeq++
131			now := svc.now()
132			created = Shift{
133				ID:        fmt.Sprintf("S%03d", d.ShiftSeq),
134				Position:  position,
135				Owner:     owner,
136				Start:     start,
137				End:       end,
138				CreatedAt: now,
139			}
140			d.Shifts = append(d.Shifts, created)
141	
142			// 为每个尚未登记说明的重叠班次保存说明；已有说明的不重复保存。
143			for _, sh := range overlapping {
144				if findNote(d, created.ID, sh.ID) != nil {
145					continue
146				}
147				d.NoteSeq++
148				x, y := notePair(created.ID, sh.ID)
149				d.Notes = append(d.Notes, OverlapNote{
150					ID:        fmt.Sprintf("N%03d", d.NoteSeq),
151					Position:  position,
152					ShiftA:    x,
153					ShiftB:    y,
154					Note:      overlapNote,
155					CreatedAt: now,
156				})
157			}
158			return nil
159		})
160		return created, err
161	}
162	
163	// AddOverlapNote 为同岗位两个重叠班次保存重叠说明。
164	func (svc *Service) AddOverlapNote(shiftA, shiftB, note string) (OverlapNote, error) {
165		note = clean(note)
166		if err := requireNonEmpty("重叠说明", note); err != nil {
167			return OverlapNote{}, err
168		}
169		if clean(shiftA) == clean(shiftB) {
170			return OverlapNote{}, fmt.Errorf("%w：重叠说明需要两个不同的班次", ErrInvalidInput)
171		}
172	
173		var saved OverlapNote
174		err := svc.store.mutate(func(d *Data) error {
175			sa, _ := findShift(d, clean(shiftA))
176			sb, _ := findShift(d, clean(shiftB))
177			if sa == nil || sb == nil {
178				return fmt.Errorf("%w：班次 %s 或 %s 不存在", ErrNotFound, shiftA, shiftB)
179			}
180			if sa.Position != sb.Position {
181				return fmt.Errorf("%w：班次 %s（%s）与 %s（%s）岗位不同，无需重叠说明",
182					ErrPositionMismatch, sa.ID, sa.Position, sb.ID, sb.Position)
183			}
184			if !intervalsOverlap(sa.Start, sa.End, sb.Start, sb.End) {
185				return fmt.Errorf("%w：班次 %s 与 %s 的时间区间不重叠（端点相接不算重叠）",
186					ErrInvalidInput, sa.ID, sb.ID)
187			}
188			d.NoteSeq++
189			x, y := notePair(sa.ID, sb.ID)
190			saved = OverlapNote{
191				ID:        fmt.Sprintf("N%03d", d.NoteSeq),
192				Position:  sa.Position,
193				ShiftA:    x,
194				ShiftB:    y,
195				Note:      note,
196				CreatedAt: svc.now(),
197			}
198			d.Notes = append(d.Notes, saved)
199			return nil
200		})
201		return saved, err
202	}
203	
204	// AddItem 向未结束班次新增事项。内容、严重程度、后续负责人必填，限制条件可空。
205	func (svc *Service) AddItem(shiftID, content string, severity Severity, constraints, followOwner string) (Item, error) {
206		shiftID = clean(shiftID)
207		content = clean(content)
208		constraints = clean(constraints)
209		followOwner = clean(followOwner)
210		if err := requireNonEmpty("事项内容", content); err != nil {
211			return Item{}, err
212		}
213		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
214			return Item{}, err
215		}
216		if !severity.valid() {
217			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
218		}
219	
220		var created Item
221		err := svc.store.mutate(func(d *Data) error {
222			sh, _ := findShift(d, shiftID)
223			if sh == nil {
224				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
225			}
226			if sh.Closed {
227				return fmt.Errorf("%w：班次 %s 已结束，不能新增事项", ErrShiftClosed, sh.ID)
228			}
229			d.ItemSeq++
230			now := svc.now()
231			created = Item{
232				ID:             fmt.Sprintf("I%03d", d.ItemSeq),
233				OriginShiftID:  sh.ID,
234				ShiftIDs:       []string{sh.ID},
235				CurrentShiftID: sh.ID,
236				Content:        content,
237				Severity:       severity,
238				Constraints:    constraints,
239				FollowOwner:    followOwner,
240				CreatedAt:      now,
241				Events: []ItemEvent{
242					{At: now, Kind: "created", Detail: "事项建立"},
243				},
244			}
245			d.Items = append(d.Items, created)
246			return nil
247		})
248		return created, err
249	}
250	
251	// UpdateItem 在事项所在班次结束前修改其内容、严重程度、限制条件和后续负责人。
252	func (svc *Service) UpdateItem(itemID, content string, severity Severity, constraints, followOwner string) (Item, error) {
253		itemID = clean(itemID)
254		content = clean(content)
255		constraints = clean(constraints)
256		followOwner = clean(followOwner)
257		if err := requireNonEmpty("事项内容", content); err != nil {
258			return Item{}, err
259		}
260		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
261			return Item{}, err
262		}
263		if !severity.valid() {
264			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
265		}
266	
267		var updated Item
268		err := svc.store.mutate(func(d *Data) error {
269			it, _ := findItem(d, itemID)
270			if it == nil {
271				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
272			}
273			sh, _ := findShift(d, it.CurrentShiftID)
274			if sh == nil || sh.Closed {
275				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，内容不能修改",
276					ErrShiftClosed, itemID, it.CurrentShiftID)
277			}
278			changes := []string{}
279			if it.Content != content {
280				changes = append(changes, "内容")
281			}
282			if it.Severity != severity {
283				changes = append(changes, "严重程度")
284			}
285			if it.Constraints != constraints {
286				changes = append(changes, "限制条件")
287			}
288			if it.FollowOwner != followOwner {
289				changes = append(changes, "后续负责人")
290			}
291			it.Content = content
292			it.Severity = severity
293			it.Constraints = constraints
294			it.FollowOwner = followOwner
295			it.Events = append(it.Events, ItemEvent{
296				At:     svc.now(),
297				Kind:   "updated",
298				Detail: "修改字段：" + joinOr(changes, "无变更"),
299			})
300			updated = *it
301			return nil
302		})
303		return updated, err
304	}
305	
306	func joinOr(xs []string, or string) string {
307		if len(xs) == 0 {
308			return or
309		}
310		return strings.Join(xs, "、")
311	}
312	
313	// CloseItem 在事项所在班次结束前关闭该事项，须填写操作人。
314	func (svc *Service) CloseItem(itemID, operator string) (Item, error) {
315		itemID = clean(itemID)
316		operator = clean(operator)
317		if err := requireNonEmpty("操作人", operator); err != nil {
318			return Item{}, err
319		}
320	
321		var closed Item
322		err := svc.store.mutate(func(d *Data) error {
323			it, _ := findItem(d, itemID)
324			if it == nil {
325				return fmt.Errorf("%w：事项 %s", ErrNotFound, itemID)
326			}
327			if it.Closed {
328				return fmt.Errorf("%w：事项 %s 已关闭，不能重复关闭", ErrHandoverState, itemID)
329			}
330			sh, _ := findShift(d, it.CurrentShiftID)
331			if sh == nil || sh.Closed {
332				return fmt.Errorf("%w：事项 %s 所属班次 %s 已结束，关闭状态不能修改",
333					ErrShiftClosed, itemID, it.CurrentShiftID)
334			}
335			now := svc.now()
336			it.Closed = true
337			it.ClosedAt = &now
338			it.CloseOperator = operator
339			it.Events = append(it.Events, ItemEvent{At: now, Kind: "closed", Operator: operator})
340			closed = *it
341			return nil
342		})
343		return closed, err
344	}
345	
346	// CloseShift 结束班次。接班交接仍有待处理或退回项时不允许结束；空清单也可以结束。
347	func (svc *Service) CloseShift(shiftID string) (Shift, error) {
348		shiftID = clean(shiftID)
349		var result Shift
350		err := svc.store.mutate(func(d *Data) error {
351			sh, _ := findShift(d, shiftID)
352			if sh == nil {
353				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
354			}
355			if sh.Closed {
356				return fmt.Errorf("%w：班次 %s 已结束", ErrShiftClosed, sh.ID)
357			}
358			for i := range d.Handovers {
359				h := &d.Handovers[i]
360				if h.ToShiftID == sh.ID && !h.Completed() {
361					return fmt.Errorf("%w：接班交接 %s 仍有未处理或退回事项，班次不能结束",
362						ErrHandoverState, h.ID)
363				}
364			}
365			now := svc.now()
366			sh.Closed = true
367			sh.ClosedAt = &now
368			result = *sh
369			return nil
370		})
371		return result, err
372	}
373	
374	// CreateHandover 由交班班次向同岗位接班班次发起交接。
375	// 重复向同一接班班次发起返回已有记录；改换接班对象报错。
376	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
377		fromShiftID = clean(fromShiftID)
378		toShiftID = clean(toShiftID)
379	
380		var result Handover
381		err := svc.store.mutate(func(d *Data) error {
382			from, _ := findShift(d, fromShiftID)
383			to, _ := findShift(d, toShiftID)
384			if from == nil {
385				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
386			}
387			if to == nil {
388				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
389			}
390			if from.ID == to.ID {
391				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
392			}
393			if from.Position != to.Position {
394				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
395					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
396			}
397			if to.Closed {
398				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
399			}
400			if to.Start.Before(from.Start) {
401				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
402					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
403					from.ID, from.Start.Format(time.RFC3339))
404			}
405	
406			// 同一交班班次只能指定一个接班对象。
407			for i := range d.Handovers {
408				if d.Handovers[i].FromShiftID == from.ID {
409					existing := &d.Handovers[i]
410					result = *existing
411					if existing.ToShiftID != to.ID {
412						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
413							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
414					}
415					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
416				}
417			}
418	
419			if !from.Closed {
420				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
421					ErrShiftNotClosed, from.ID)
422			}
423			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasNote(d, from.ID, to.ID) {
424				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
425					ErrOverlap, from.ID, to.ID)
426			}
427	
428			entries := []HandoverEntry{}
429			for i := range d.Items {
430				it := &d.Items[i]
431				if it.CurrentShiftID == from.ID && !it.Closed {
432					entries = append(entries, HandoverEntry{
433						ItemID:      it.ID,
434						Content:     it.Content,
435						Severity:    it.Severity,
436						Constraints: it.Constraints,
437						FollowOwner: it.FollowOwner,
438						Status:      EntryPending,
439					})
440				}
441			}
442			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
443	
444			d.HandoverSeq++
445			now := svc.now()
446			h := Handover{
447				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
448				Position:    from.Position,
449				FromShiftID: from.ID,
450				ToShiftID:   to.ID,
451				CreatedAt:   now,
452				Entries:     entries,
453			}
454			if len(entries) == 0 {
455				// 空清单直接完成。
456				h.CompletedAt = &now
457			}
458			d.Handovers = append(d.Handovers, h)
459			result = h
460			return nil
461		})
462		return result, err
463	}
464	
465	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
466	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
467	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
468		handoverID = clean(handoverID)
469		itemID = clean(itemID)
470		operator = clean(operator)
471		reason = clean(reason)
472		trackingNote = clean(trackingNote)
473		nextFollowOwner = clean(nextFollowOwner)
474	
475		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
476			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
477		}
478		if err := requireNonEmpty("操作人", operator); err != nil {
479			return Handover{}, err
480		}
481	
482		var result Handover
483		err := svc.store.mutate(func(d *Data) error {
484			h, _ := findHandover(d, handoverID)
485			if h == nil {
486				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
487			}
488			e, _ := findEntry(h, itemID)
489			if e == nil {
490				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
491			}
492			if e.Status.Received() {
493				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
494					ErrHandoverState, e.ItemID, e.Status.Label())
495			}
496			switch action {
497			case ActionReturn:
498				if err := requireNonEmpty("退回原因", reason); err != nil {
499					return err
500				}
501			case ActionTrack:
502				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
503					return err
504				}
505				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
506					return err
507				}
508			}
509	
510			now := svc.now()
511			switch action {
512			case ActionConfirm:
513				e.Status = EntryConfirmed
514			case ActionTrack:
515				e.Status = EntryTracking
516				e.TrackingNote = trackingNote
517				e.FollowOwner = nextFollowOwner
518			case ActionReturn:
519				e.Status = EntryReturned
520				e.Rounds = append(e.Rounds, ReturnRound{
521					Seq:            len(e.Rounds) + 1,
522					ReturnedAt:     now,
523					ReturnOperator: operator,
524					Reason:         reason,
525				})
526			}
527			e.Operator = operator
528			e.ProcessedAt = &now
529	
530			if action != ActionReturn {
531				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
532				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
533					it.CurrentShiftID = h.ToShiftID
534					if !contains(it.ShiftIDs, h.ToShiftID) {
535						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
536					}
537					detail := "接班班次 " + h.ToShiftID + " 接收：" + e.Status.Label()
538					if action == ActionTrack {
539						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
540						it.FollowOwner = nextFollowOwner
541						detail += "；跟踪说明：" + trackingNote + "；后续负责人：" + nextFollowOwner
542					}
543					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
544				}
545			}
546	
547			if h.Completed() && h.CompletedAt == nil {
548				h.CompletedAt = &now
549			}
550			result = *h
551			return nil
552		})
553		return result, err
554	}
555	
556	func contains(xs []string, x string) bool {
557		for _, v := range xs {
558			if v == x {
559				return true
560			}
561		}
562		return false
563	}
564	
565	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
566	// 只有该项恢复待处理，既有接收结果、原文与退回原因均不变。
567	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
568		handoverID = clean(handoverID)
569		itemID = clean(itemID)
570		operator = clean(operator)
571		supplement = clean(supplement)
572		if err := requireNonEmpty("操作人", operator); err != nil {
573			return Handover{}, err
574		}
575		if err := requireNonEmpty("补充说明", supplement); err != nil {
576			return Handover{}, err
577		}
578	
579		var result Handover
580		err := svc.store.mutate(func(d *Data) error {
581			h, _ := findHandover(d, handoverID)
582			if h == nil {
583				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
584			}
585			e, _ := findEntry(h, itemID)
586			if e == nil {
587				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
588			}
589			if e.Status != EntryReturned {
590				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
591					ErrHandoverState, e.ItemID, e.Status.Label())
592			}
593			if len(e.Rounds) == 0 {
594				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
595			}
596			round := &e.Rounds[len(e.Rounds)-1]
597			if round.ResubmittedAt != nil {
598				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
599			}
600			now := svc.now()
601			round.Supplement = supplement
602			round.SupplementOperator = operator
603			round.SupplementAt = &now
604			round.ResubmittedAt = &now
605			e.Status = EntryPending
606			result = *h
607			return nil
608		})
609		return result, err
610	}
611	
612	// GetShift 按编号查询班次。
613	func (svc *Service) GetShift(id string) (Shift, error) {
614		sh, _ := findShift(&svc.store.data, clean(id))
615		if sh == nil {
616			return Shift{}, fmt.Errorf("%w：班次 %s", ErrNotFound, id)
617		}
618		return *sh, nil
619	}
620	
621	// ListShifts 返回全部班次，按编号排序。
622	func (svc *Service) ListShifts() []Shift {
623		out := append([]Shift(nil), svc.store.data.Shifts...)
624		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
625		return out
626	}
627	
628	// GetItem 按稳定编号查询事项。
629	func (svc *Service) GetItem(id string) (Item, error) {
630		it, _ := findItem(&svc.store.data, clean(id))
631		if it == nil {
632			return Item{}, fmt.Errorf("%w：事项 %s", ErrNotFound, id)
633		}
634		return *it, nil
635	}
636	
637	// GetHandover 按编号查询交接。
638	func (svc *Service) GetHandover(id string) (Handover, error) {
639		h, _ := findHandover(&svc.store.data, clean(id))
640		if h == nil {
641			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
642		}
643		return *h, nil
644	}
645	
646	// ListHandovers 返回全部交接记录，按编号排序。
647	func (svc *Service) ListHandovers() []Handover {
648		out := append([]Handover(nil), svc.store.data.Handovers...)
649		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
650		return out
651	}
652	
653	// OverlapNotes 返回涉及指定班次的全部重叠说明。
654	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
655		shiftID = clean(shiftID)
656		out := []OverlapNote{}
657		for _, n := range svc.store.data.Notes {
658			if n.ShiftA == shiftID || n.ShiftB == shiftID {
659				out = append(out, n)
660			}
661		}
662		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
663		return out
664	}
665	
666	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
667	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
668		shiftID = clean(shiftID)
669		d := &svc.store.data
670		rep := ShiftReport{Results: map[string][]EntryView{}}
671		sh, _ := findShift(d, shiftID)
672		if sh == nil {
673			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
674		}
675		rep.Shift = *sh
676	
677		for _, n := range d.Notes {
678			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
679				rep.OverlapNotes = append(rep.OverlapNotes, n)
680			}
681		}
682		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
683	
684		for _, it := range d.Items {
685			if it.OriginShiftID == sh.ID || it.CurrentShiftID == sh.ID || contains(it.ShiftIDs, sh.ID) {
686				rep.Items = append(rep.Items, it)
687			}
688		}
689		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
690	
691		for i := range d.Handovers {
692			h := &d.Handovers[i]
693			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
694			if !involved {
695				continue
696			}
697			if h.FromShiftID == sh.ID {
698				cp := *h
699				rep.Outgoing = &cp
700			}
701			if h.ToShiftID == sh.ID {
702				rep.Incoming = append(rep.Incoming, *h)
703			}
704			for j := range h.Entries {
705				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
706					HandoverID: h.ID,
707					FromShift:  h.FromShiftID,
708					ToShift:    h.ToShiftID,
709					Entry:      h.Entries[j],
710				})
711			}
712		}
713		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
714		for k := range rep.Results {
715			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
716		}
717		return rep, nil
718	}
